"""Build public discovery pages; private submissions remain in C-Suiteware."""
from pathlib import Path
import re,html
ROOT=Path(__file__).resolve().parents[1]/'website-preview'
BASE='/website-preview'
template=(ROOT/'contact/index.html').read_text()
trail=re.search(r'<section class="carmen-trail".*?</section>',template,re.S).group()
def sec(body,cls=''):
 return '<section class="'+cls+'"><div class="wrap">'+body+'</div></section>'
def follow():
 return sec('<p class="eyebrow">Keep the connection going</p><h2>Follow the people opening doors.</h2><p>Discover local businesses, community connections and what’s coming next.</p><div class="email-actions"><a class="button" href="https://www.instagram.com/doitwithtlc/">Follow TLC · @doitwithtlc</a><a class="button secondary" href="https://www.instagram.com/bblocala/">Follow BBLO · @bblocala</a></div>','social-invitation')
def embed(id,title):
 url='https://api.leadconnectorhq.com/widget/form/'+id
 return '<p><a class="text-link" href="'+url+'">Open '+title+' in its own page →</a></p><iframe class="crm-intake-frame" src="'+url+'" title="'+title+'" loading="lazy" referrerpolicy="strict-origin-when-cross-origin" style="width:100%;height:1850px;border:0;border-radius:12px;background:#fff"></iframe>'
def page(route,title,desc,body):
 s=re.sub(r'<title>.*?</title>','<title>'+title+'</title>',template)
 s=re.sub(r'<meta name="description" content="[^"]*">','<meta name="description" content="'+desc+'">',s)
 s=re.sub(r'<meta property="og:title" content="[^"]*">','<meta property="og:title" content="'+title+'">',s)
 s=re.sub(r'<meta property="og:description" content="[^"]*">','<meta property="og:description" content="'+desc+'">',s)
 s=s.replace('https://doitwithtlc.com/website-preview/contact/','https://doitwithtlc.com'+BASE+route).replace('https://doitwithtlc.com/contact/','https://doitwithtlc.com'+BASE+route)
 s=re.sub(r'(<main\b[^>]*>).*?(</main>)',lambda m:m[1]+body+follow()+trail+m[2],s,flags=re.S)
 p=ROOT/route.strip('/')/'index.html';p.parent.mkdir(parents=True,exist_ok=True);p.write_text(s)
nom=sec('<p class="eyebrow">Local Business Spotlights &amp; Nominations</p><h1>They show up for us.<br><em>Let’s show up for them.</em></h1><p class="lead">Know a local small business making a difference? Tell us who they are, what they do and the moment that made you say, “More people need to know about them.”</p><a class="button" href="#nominate">Nominate a local business</a>','hero')
nom+=sec('<div class="grid three"><article class="card"><h2>Notice the difference.</h2><p>Recognize a business that serves its neighbors, opens doors or goes the extra mile. A specific story matters more than a follower count.</p></article><article class="card"><h2>Tell us the story.</h2><p>Share your own experience and the business’s contact details so our team can check the nomination.</p></article><article class="card"><h2>Help us verify it.</h2><p>We may contact you and the business before considering a spotlight. Nominations stay private during review.</p></article></div>')
nom+=sec('<h2>A nomination starts with a real connection.</h2><p>Please nominate a business you do not own, manage or represent. Use your own contact information and explain how you know the business. Self-nominations are not eligible for this process.</p><p>We review identity, contact details, social profiles, duplicate submissions and the example you provide. A declaration alone cannot prove independence; our team makes the verification decision.</p><p>Submitting does not guarantee publication, an award or gala eligibility. We’ll obtain permission before publishing a business spotlight. Please provide business contact details intended for business inquiries.</p>')
nom+=sec('<div id="nominate"><p class="eyebrow">Give a local business its moment</p><h2>Who deserves to be seen?</h2><p>Your details identify you as the nominator. The business details are collected separately for verification. Required fields include the business’s phone, email, social links, location and your reason; the owner’s name is optional.</p>'+embed('F36mpf7ahV6z2bzEkNvo','local business nomination form')+'</div>','intake-section')
nom+=sec('<p class="eyebrow">Local business spotlights</p><h2>The stories begin here.</h2><p>Approved spotlights will appear here after verification and permission. Help us discover the first businesses worth introducing.</p>')
page('/local-business-spotlights/','Local Business Spotlights &amp; Nominations | TLC','Nominate a local small business making a difference. Share a specific story and business contact details for private TLC review.',nom)
chapter=sec('<p class="eyebrow">The next BBLO chapter</p><h1>Where should we<br><em>open doors next?</em></h1><p class="lead">Your community. Your connections. Your voice. Tell us where you’d like to see a BBLO chapter—and when you could actually be in the room.</p><a class="button" href="#chapter-interest">Put your community on the map</a>','hero')
chapter+=sec('<div class="grid three"><article class="card"><h2>Tell us where.</h2><p>Share the city and county you want us to consider, along with what your local business community needs.</p></article><article class="card"><h2>Choose what works.</h2><p>Select every day and time range you could attend. Use your local time so we can compare realistic options.</p></article><article class="card"><h2>Build with purpose.</h2><p>We’ll use the responses to assess local interest, meeting schedules and people who may help bring a chapter together.</p></article></div><p>This is an interest survey. It does not create a membership, reserve a place or announce a confirmed chapter. Locations and schedules will be decided after review.</p>')
chapter+=sec('<div id="chapter-interest"><p class="eyebrow">Help shape what comes next</p><h2>Bring BBLO closer to you.</h2><p>Your response will be saved in our CRM as chapter interest. You can tell us whether BBLO may email you about planning in your area.</p>'+embed('cIvDMdOTPQ8o8SiWcQuW','BBLO chapter interest form')+'</div>','intake-section')
page('/bblo/chapters/','Bring BBLO to Your Community | Chapter Interest | TLC','Tell BBLO which city needs a chapter and select the meeting days and times that work for you. Help shape future business connections.',chapter)
# Primary discovery links work without JavaScript on main landing pages.
for route,body in [('home',sec('<p class="eyebrow">Local businesses. Shared momentum.</p><h2>Help good businesses get seen.</h2><p>Know a small business making a difference? Tell us the story behind it.</p><a class="button" href="'+BASE+'/local-business-spotlights/">Local Business Spotlights &amp; Nominations</a>')),('bblo',sec('<p class="eyebrow">Where should BBLO grow?</p><h2>Put your community on the map.</h2><p>Tell us where a new chapter could make a difference and which meeting days and times would work.</p><a class="button" href="'+BASE+'/bblo/chapters/">Bring BBLO to your community</a>'))]:
 p=ROOT/route/'index.html';s=p.read_text();s=re.sub(r'<!-- community-discovery-start -->.*?<!-- community-discovery-end -->','',s,flags=re.S);s=s.replace('<section class="carmen-trail"','<!-- community-discovery-start -->'+body+follow()+'<!-- community-discovery-end --><section class="carmen-trail"',1);p.write_text(s)
